 SpecterX Purview Integration Setup Tool – Guided UI (WPF)
 Version: 1.0
 Author: SpecterX
===================================================================== #>

# ---------------------- Config ---------------------------
$AppDisplayNameDefault = "SpecterX Purview Integration"
$LogRootPreferred      = "C:\Windows\Logs\SpecterX"
$LogRootFallback       = Join-Path $env:TEMP "SpecterX"

# ---------------------- SpecterX Logo -------------------
$LogoBase64 = @'

'@

# ---------------------- Session State --------------------
$global:State = [ordered]@{
  PS7OK                = $false
  GraphModuleOK        = $false
  AppDisplayName       = $AppDisplayNameDefault
  LogFile              = $null
  StatePath            = $null
  TenantId             = $null
  TenantDomain         = $null
  ApplicationObjectId  = $null
  ApplicationClientId  = $null
  ClientSecretValue    = $null
}

# ---------------------- Logging --------------------------
function Start-SpxLogging {
  $script:LogRoot = $LogRootPreferred
  try {
    if (-not (Test-Path $script:LogRoot)) { New-Item -ItemType Directory -Path $script:LogRoot -Force | Out-Null }
    $global:State.LogFile = Join-Path $script:LogRoot ("PurviewSetup-" + (Get-Date -Format "yyyyMMdd_HHmmss") + ".log")
    Start-Transcript -Path $global:State.LogFile -Append -Force | Out-Null
  } catch {
    $script:LogRoot = $LogRootFallback
    if (-not (Test-Path $script:LogRoot)) { New-Item -ItemType Directory -Path $script:LogRoot -Force | Out-Null }
    $global:State.LogFile = Join-Path $script:LogRoot ("PurviewSetup-" + (Get-Date -Format "yyyyMMdd_HHmmss") + ".log")
    try { Start-Transcript -Path $global:State.LogFile -Append -Force | Out-Null } catch {}
  }
  $global:State.StatePath = Join-Path $script:LogRoot "SpecterX-Purview-State.json"
}
function Stop-SpxLogging { try { Stop-Transcript | Out-Null } catch {} }
Start-SpxLogging

# ---------------------- WPF + Helpers --------------------
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

function New-Window {
  param([string]$Title = "SpecterX Purview Setup", [int]$Width = 920, [int]$Height = 620, [switch]$IsDialog)
  $win = New-Object System.Windows.Window
  $win.Title = $Title
  $win.Width = $Width
  $win.Height = $Height
  $win.WindowStartupLocation = 'CenterScreen'
  $win.Background = 'White'
  $win.ResizeMode = if ($IsDialog) { 'CanMinimize' } else { 'CanResize' }
  return $win
}

function Load-Logo {
  try {
    if ([string]::IsNullOrWhiteSpace($LogoBase64)) { throw "No embedded logo." }
    $bytes = [Convert]::FromBase64String($LogoBase64)
    $ms = New-Object System.IO.MemoryStream(,$bytes)
    $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
    $bmp.BeginInit(); $bmp.StreamSource = $ms; $bmp.CacheOption = 'OnLoad'; $bmp.EndInit()

    $img = New-Object System.Windows.Controls.Image
    $img.Source = $bmp
    $img.Height = 56
    $img.Margin = '0,8,0,8'
    return $img
  } catch {
    $txt = New-Object System.Windows.Controls.TextBlock
    $txt.Text = "SPECTERX"
    $txt.FontSize = 28
    $txt.FontWeight = 'Bold'
    $txt.Foreground = 'DodgerBlue'
    $txt.Margin = '0,8,0,8'
    return $txt
  }
}


function New-Button([string]$content) {
  $b = New-Object System.Windows.Controls.Button
  $b.Content = $content
  $b.Margin = '0,6,0,0'
  $b.Padding = '10,6'
  $b.HorizontalContentAlignment = 'Left'
  return $b
}

function Append-Output($box, [string]$line) {
  $box.AppendText($line + [Environment]::NewLine)
  $box.ScrollToEnd()
}

function Append-Status([string]$text) {
  if ($null -ne $global:StatusBox) { Append-Output $global:StatusBox $text }
}

function Save-State {
  try {
    $json = $global:State | ConvertTo-Json -Depth 8
    Set-Content -Path $global:State.StatePath -Value $json -NoNewline -Encoding UTF8
  } catch {}
}

function Load-State {
  try {
    if (Test-Path $global:State.StatePath) {
      $s = Get-Content -Raw -Path $global:State.StatePath | ConvertFrom-Json
      foreach ($k in $s.PSObject.Properties.Name) {
        if ($global:State.Contains($k)) { $global:State[$k] = $s.$k }
      }
    }
  } catch {}
}

function Start-AsyncConsole {
  param([Parameter(Mandatory)][string]$Title, [Parameter(Mandatory)][string]$Command)
  Start-Process pwsh -ArgumentList @(
    '-NoExit', '-NoLogo', '-Command',
@"
`$Host.UI.RawUI.WindowTitle = '$Title';
Write-Host '=== $Title ===' -ForegroundColor Cyan;
try {
$Command
  Write-Host ''
  Write-Host 'Success.' -ForegroundColor Green
} catch {
  Write-Host ''
  Write-Host ('ERROR: ' + `$_.Exception.Message) -ForegroundColor Red
}
Write-Host ''
Write-Host 'Close this window when done.' -ForegroundColor Yellow
"@
  ) | Out-Null
}

# ---------------------- Step 1: Prereqs -------------------
function Step1_CheckPrereqs($outBox) {
  Append-Output $outBox "Checking PowerShell version..."
  if ($PSVersionTable.PSVersion.Major -ge 7) {
    $global:State.PS7OK = $true
    Append-Output $outBox "PowerShell 7+ OK ($($PSVersionTable.PSVersion))."
  } else {
    $global:State.PS7OK = $false
    Append-Output $outBox "PowerShell 7+ REQUIRED. Current: $($PSVersionTable.PSVersion)."
  }

  Append-Output $outBox "Checking Microsoft.Graph module..."
  $mg = Get-Module -ListAvailable Microsoft.Graph
  if ($mg) {
    $global:State.GraphModuleOK = $true
    Append-Output $outBox "Microsoft.Graph is installed."
  } else {
    $global:State.GraphModuleOK = $false
    Append-Output $outBox "Microsoft Graph PowerShell SDK is REQUIRED."
    Append-Output $outBox "Manual install: Install-Module Microsoft.Graph -Scope CurrentUser"
  }

  if ($global:State.PS7OK -and $global:State.GraphModuleOK) {
    Append-Output $outBox "Prerequisites complete."
  } else {
    Append-Output $outBox "Prerequisites missing. Use the Fix buttons, then click Run Check again."
  }
  Save-State
}

function Show-PrereqDialog {
  $dlg = New-Window -Title "Step 1 - Check prerequisites" -Width 780 -Height 620 -IsDialog
  $root = New-Object System.Windows.Controls.Grid
  $root.Margin = '16'
  $dlg.Content = $root

  foreach ($h in @('Auto', '*', 'Auto', 'Auto')) {
    $rd = New-Object System.Windows.Controls.RowDefinition
    $rd.Height = if ($h -eq '*') { '1*' } else { 'Auto' }
    $root.RowDefinitions.Add($rd)
  }

  $explain = New-Object System.Windows.Controls.TextBlock
  $explain.Text = "This verifies PowerShell 7+ and Microsoft Graph PowerShell SDK. No tenant changes are made."
  $explain.TextWrapping = 'Wrap'
  $explain.Margin = '0,0,0,10'
  $root.Children.Add($explain) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($explain, 0)

  $outBox = New-Object System.Windows.Controls.TextBox
  $outBox.IsReadOnly = $true
  $outBox.VerticalScrollBarVisibility = 'Auto'
  $outBox.TextWrapping = 'Wrap'
  $outBox.FontFamily = 'Consolas'
  $root.Children.Add($outBox) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($outBox, 1)

  $progress = New-Object System.Windows.Controls.ProgressBar
  $progress.Height = 12
  $progress.Visibility = 'Collapsed'
  $progress.Margin = '0,8,0,0'
  $root.Children.Add($progress) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($progress, 2)

  $btnPanel = New-Object System.Windows.Controls.WrapPanel
  $btnPanel.HorizontalAlignment = 'Right'
  $btnPanel.Margin = '0,10,0,0'
  $root.Children.Add($btnPanel) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($btnPanel, 3)

  $runBtn   = New-Button "Run Check"
  $fixGraph = New-Button "Fix: Install Microsoft.Graph"
  $ps7Page  = New-Button "Fix: Open PowerShell 7 Download"
  $closeBtn = New-Button "Close"
  @($runBtn, $fixGraph, $ps7Page, $closeBtn) | ForEach-Object { $btnPanel.Children.Add($_) | Out-Null }

  $runBtn.Add_Click({
    $outBox.Clear()
    $progress.Visibility = 'Visible'
    $progress.IsIndeterminate = $true
    try { Step1_CheckPrereqs $outBox } finally {
      $progress.IsIndeterminate = $false
      $progress.Visibility = 'Collapsed'
    }
  })

  $fixGraph.Add_Click({
    Start-AsyncConsole -Title "Install Microsoft.Graph" -Command @"
if (-not (Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue)) { Register-PSRepository -Default }
if ((Get-PSRepository -Name PSGallery).InstallationPolicy -ne 'Trusted') { Set-PSRepository -Name PSGallery -InstallationPolicy Trusted }
Install-Module Microsoft.Graph -Scope CurrentUser -Force -AllowClobber -ErrorAction Stop
Write-Host 'Microsoft.Graph installed successfully.' -ForegroundColor Green
"@
    Append-Output $outBox "Opened a new PowerShell window to install Microsoft.Graph."
    Append-Output $outBox "After it completes, click 'Run Check'."
  })

  $ps7Page.Add_Click({ Start-Process "https://aka.ms/PowerShell-Release" | Out-Null })
  $closeBtn.Add_Click({ $dlg.Close() })
  $dlg.ShowDialog() | Out-Null
}

# ---------------------- Dialog Builder --------------------
function Show-StepDialog {
  param(
    [string]$Title,
    [string]$Explanation,
    [scriptblock]$BuildInputs,
    [scriptblock]$OnRun
  )

  $dlg = New-Window -Title $Title -Width 780 -Height 620 -IsDialog
  $root = New-Object System.Windows.Controls.Grid
  $root.Margin = '16'
  $dlg.Content = $root

  foreach ($h in @('Auto', 'Auto', '*', 'Auto', 'Auto')) {
    $rd = New-Object System.Windows.Controls.RowDefinition
    $rd.Height = if ($h -eq '*') { '1*' } else { 'Auto' }
    $root.RowDefinitions.Add($rd)
  }

  $explain = New-Object System.Windows.Controls.TextBlock
  $explain.Text = $Explanation
  $explain.TextWrapping = 'Wrap'
  $explain.Margin = '0,0,0,10'
  $root.Children.Add($explain) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($explain, 0)

  $inputsPanel = New-Object System.Windows.Controls.StackPanel
  $inputsPanel.Margin = '0,0,0,10'
  $root.Children.Add($inputsPanel) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($inputsPanel, 1)

  $controls = @{}
  if ($BuildInputs) { $controls = & $BuildInputs $inputsPanel; if (-not $controls) { $controls = @{} } }

  $outBox = New-Object System.Windows.Controls.TextBox
  $outBox.IsReadOnly = $true
  $outBox.VerticalScrollBarVisibility = 'Auto'
  $outBox.TextWrapping = 'Wrap'
  $outBox.FontFamily = 'Consolas'
  $root.Children.Add($outBox) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($outBox, 2)

  $progress = New-Object System.Windows.Controls.ProgressBar
  $progress.Height = 12
  $progress.Visibility = 'Collapsed'
  $progress.Margin = '0,8,0,0'
  $root.Children.Add($progress) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($progress, 3)

  $btnPanel = New-Object System.Windows.Controls.StackPanel
  $btnPanel.Orientation = 'Horizontal'
  $btnPanel.HorizontalAlignment = 'Right'
  $btnPanel.Margin = '0,10,0,0'
  $root.Children.Add($btnPanel) | Out-Null
  [System.Windows.Controls.Grid]::SetRow($btnPanel, 4)

  $runBtn = New-Button "Run"
  $closeBtn = New-Button "Close"
  $btnPanel.Children.Add($runBtn) | Out-Null
  $btnPanel.Children.Add($closeBtn) | Out-Null

  $runBtn.Add_Click({
    try {
      $vals = @{}
      foreach ($k in $controls.Keys) {
        $ctrl = $controls[$k]
        if ($ctrl -is [System.Windows.Controls.CheckBox]) { $vals[$k] = $ctrl.IsChecked }
        elseif ($ctrl -is [System.Windows.Controls.TextBox]) { $vals[$k] = $ctrl.Text }
        else { $vals[$k] = $ctrl }
      }
      $runBtn.IsEnabled = $false
      $progress.Visibility = 'Visible'
      $progress.IsIndeterminate = $true
      & $OnRun $vals $outBox
    } catch {
      Append-Output $outBox ("Unhandled error: " + $_.Exception.Message)
    } finally {
      $progress.IsIndeterminate = $false
      $progress.Visibility = 'Collapsed'
      $runBtn.IsEnabled = $true
    }
  })

  $closeBtn.Add_Click({ $dlg.Close() })
  $dlg.ShowDialog() | Out-Null
}

