function Add-NumberedRow {
  param([int]$Index, [string]$Text, [scriptblock]$OnClick)
  $rowGrid = New-Object System.Windows.Controls.Grid
  $rowGrid.Margin = '0,4,0,0'
  $c1 = New-Object System.Windows.Controls.ColumnDefinition
  $c1.Width = '35'
  $c2 = New-Object System.Windows.Controls.ColumnDefinition
  $c2.Width = '1*'
  $rowGrid.ColumnDefinitions.Add($c1)
  $rowGrid.ColumnDefinitions.Add($c2)

  $num = New-Object System.Windows.Controls.TextBlock
  $num.Text = ("{0})" -f $Index)
  $num.VerticalAlignment = 'Center'
  $num.Margin = '0,0,6,0'
  $rowGrid.Children.Add($num) | Out-Null
  [System.Windows.Controls.Grid]::SetColumn($num, 0)

  $btn = New-Button $Text
  $rowGrid.Children.Add($btn) | Out-Null
  [System.Windows.Controls.Grid]::SetColumn($btn, 1)
  if ($OnClick) { $btn.Add_Click($OnClick) }
  $left.Children.Add($rowGrid) | Out-Null
}

$right = New-Object System.Windows.Controls.StackPanel
$grid.Children.Add($right) | Out-Null
[System.Windows.Controls.Grid]::SetColumn($right, 1)

