Append-Output $status $welcome

# ---------------------- Step 1 ----------------------------
Add-NumberedRow -Index 1 -Text "Check endpoint prerequisites" -OnClick { Show-PrereqDialog }

# ---------------------- Step 2 ----------------------------
Add-NumberedRow -Index 2 -Text "Connect to Entra ID" -OnClick {
  Show-StepDialog -Title "Step 2 - Connect to Entra ID" -Explanation @"
This connects to Microsoft Graph interactively and saves:
 - Tenant ID
 - Tenant domain
"@ -BuildInputs { param($p) @{} } -OnRun {
    param($vals, $out)
    $statePathLiteral = $global:State.StatePath.Replace('\', '\\')

    Append-Status "=== SpecterX Purview: Connect to Entra ID ==="
    Append-Output $out "Launching interactive browser sign-in..."

    Start-AsyncConsole -Title "SpecterX Purview: Connect to Entra ID" -Command @"
`$scopes = 'Application.ReadWrite.All','Directory.Read.All'
Connect-MgGraph -Scopes `$scopes -NoWelcome
`$ctx = Get-MgContext
if (-not `$ctx -or [string]::IsNullOrWhiteSpace(`$ctx.TenantId)) { throw 'No tenant in context.' }
`$org = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/organization'
if (-not `$org.value -or `$org.value.Count -eq 0) { throw 'No organization returned.' }
`$tenantId = `$ctx.TenantId
`$tenantDomain = (`$org.value[0].verifiedDomains | Where-Object { `$_.initial -eq `$true } | Select-Object -First 1 -ExpandProperty name)
if (-not `$tenantDomain) { `$tenantDomain = `$org.value[0].verifiedDomains[0].name }

if (Test-Path '$statePathLiteral') { `$curr = Get-Content -Raw -Path '$statePathLiteral' | ConvertFrom-Json } else { `$curr = [pscustomobject]@{} }
`$curr | Add-Member -NotePropertyName 'TenantId' -NotePropertyValue `$tenantId -Force
`$curr | Add-Member -NotePropertyName 'TenantDomain' -NotePropertyValue `$tenantDomain -Force
`$json = `$curr | ConvertTo-Json -Depth 8
Set-Content -Path '$statePathLiteral' -Value `$json -NoNewline -Encoding UTF8

Write-Host ('Tenant Domain : ' + `$tenantDomain)
Write-Host ('Tenant ID     : ' + `$tenantId)
Write-Host 'Connected successfully and saved tenant info.' -ForegroundColor Green
"@

    Append-Output $out "Opened console for Step 2."
    $attempts = 0
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromSeconds(1)
    $timer.Add_Tick({
      $attempts++
      try {
        if (Test-Path $global:State.StatePath) {
          $s = Get-Content -Raw -Path $global:State.StatePath | ConvertFrom-Json
          if ($s -and $s.TenantId -and $s.TenantDomain) {
            $timer.Stop()
            $global:State.TenantId = $s.TenantId
            $global:State.TenantDomain = $s.TenantDomain
            Save-State
            Append-Status ""
            Append-Status ("Tenant Domain : {0}" -f $s.TenantDomain)
            Append-Status ("Tenant ID     : {0}" -f $s.TenantId)
            Append-Status "Connected successfully."
            Append-Output $out "Tenant info detected in state file."
          }
        }
      } catch {}
      if ($attempts -ge 120) { $timer.Stop() }
    })
    $timer.Start()
  }
}

# ---------------------- Step 3 ----------------------------
Add-NumberedRow -Index 3 -Text "Create app registration" -OnClick {
  Show-StepDialog -Title "Step 3 - Create app registration" -Explanation @"
Creates the app registration (editable name).
This step also ensures a service principal exists for the app.
"@ -BuildInputs {
    param($panel)
    $tenantId = ""; $tenantDomain = ""; $appName = $global:State.AppDisplayName
    if (Test-Path $global:State.StatePath) {
      try {
        $s = Get-Content -Raw -Path $global:State.StatePath | ConvertFrom-Json
        $tenantId = $s.TenantId
        $tenantDomain = $s.TenantDomain
        if ($s.AppDisplayName) { $appName = [string]$s.AppDisplayName }
      } catch {}
    }

    $lblTid = New-Object System.Windows.Controls.TextBlock
    $lblTid.Text = "Tenant ID (from Step 2):"
    $panel.Children.Add($lblTid) | Out-Null
    $tbTid = New-Object System.Windows.Controls.TextBox
    $tbTid.Text = ($tenantId ?? "")
    $panel.Children.Add($tbTid) | Out-Null

    $lblDom = New-Object System.Windows.Controls.TextBlock
    $lblDom.Text = "Tenant Domain (optional fallback):"
    $panel.Children.Add($lblDom) | Out-Null
    $tbDom = New-Object System.Windows.Controls.TextBox
    $tbDom.Text = ($tenantDomain ?? "")
    $panel.Children.Add($tbDom) | Out-Null

    $lblApp = New-Object System.Windows.Controls.TextBlock
    $lblApp.Text = "Application Name:"
    $panel.Children.Add($lblApp) | Out-Null
    $tbApp = New-Object System.Windows.Controls.TextBox
    $tbApp.Text = ($appName ?? "SpecterX Purview Integration")
    $panel.Children.Add($tbApp) | Out-Null

    @{ TenantId = $tbTid; TenantDomain = $tbDom; AppName = $tbApp }
  } -OnRun {
    param($vals, $out)
    $tenantId  = ($vals.TenantId ?? "").Trim()
    $tenantDom = ($vals.TenantDomain ?? "").Trim()
    $appName   = ($vals.AppName ?? "").Trim()
    $tenantHint = if (-not [string]::IsNullOrWhiteSpace($tenantId)) { $tenantId } elseif (-not [string]::IsNullOrWhiteSpace($tenantDom)) { $tenantDom } else { "" }
    if ([string]::IsNullOrWhiteSpace($tenantHint)) {
      Append-Output $out "Please provide Tenant ID or Tenant Domain."
      return
    }
    if ([string]::IsNullOrWhiteSpace($appName)) {
      Append-Output $out "Please provide an Application Name."
      return
    }

    $statePathLiteral = $global:State.StatePath.Replace('\', '\\')
    $appNameLiteral = $appName.Replace("'","''")

    Start-AsyncConsole -Title "SpecterX Purview: Create App Registration" -Command @"
`$tenantHint = '$tenantHint'
`$statePath = '$statePathLiteral'
`$appName = '$appNameLiteral'
`$requiredScopes = 'Application.ReadWrite.All','Directory.ReadWrite.All'

Write-Host 'Connecting to Microsoft Graph...' -ForegroundColor Yellow
Connect-MgGraph -Scopes `$requiredScopes -TenantId `$tenantHint -NoWelcome

Write-Host ('Creating app registration: ' + `$appName) -ForegroundColor Yellow
`$app = New-MgApplication -DisplayName `$appName -SignInAudience 'AzureADMyOrg'
if (-not `$app -or -not `$app.Id -or -not `$app.AppId) { throw 'Failed to create application.' }
Write-Host ('Application ObjectId: ' + `$app.Id)
Write-Host ('Application ClientId: ' + `$app.AppId)

Write-Host 'Ensuring service principal exists for app...' -ForegroundColor Yellow
`$sp = `$null
for (`$i = 0; `$i -lt 8 -and -not `$sp; `$i++) {
  try {
    `$sp = Get-MgServicePrincipal -Filter ("appId eq '" + `$app.AppId + "'") -ConsistencyLevel eventual -CountVariable c | Select-Object -First 1
    if (-not `$sp) { Start-Sleep -Seconds 2 }
  } catch { Start-Sleep -Seconds 2 }
}
if (-not `$sp) { `$sp = New-MgServicePrincipal -AppId `$app.AppId }
if (-not `$sp -or -not `$sp.Id) { throw 'Could not create/find service principal for app.' }
Write-Host ('Service Principal ObjectId: ' + `$sp.Id)

if (Test-Path `$statePath) { `$curr = Get-Content -Raw -Path `$statePath | ConvertFrom-Json } else { `$curr = [pscustomobject]@{} }
`$curr | Add-Member -NotePropertyName 'ApplicationObjectId' -NotePropertyValue `$app.Id -Force
`$curr | Add-Member -NotePropertyName 'ApplicationClientId' -NotePropertyValue `$app.AppId -Force
`$curr | Add-Member -NotePropertyName 'ServicePrincipalObjectId' -NotePropertyValue `$sp.Id -Force
`$curr | Add-Member -NotePropertyName 'AppDisplayName' -NotePropertyValue `$appName -Force
`$json = `$curr | ConvertTo-Json -Depth 10
Set-Content -Path `$statePath -Value `$json -NoNewline -Encoding UTF8
Write-Host 'Saved app and service principal info to state file.' -ForegroundColor DarkGreen
"@
    Append-Output $out "Opened console for Step 3."
    $global:State.AppDisplayName = $appName
    Save-State
  }
}

# ---------------------- Step 4 ----------------------------
Add-NumberedRow -Index 4 -Text "Create client secret" -OnClick {
  Show-StepDialog -Title "Step 4 - Create client secret" -Explanation @"
Creates a client secret for the existing app registration and stores it in state.
"@ -BuildInputs {
    param($panel)
    $appObjectId = ""
    $appClientId = ""
    if (Test-Path $global:State.StatePath) {
      try {
        $s = Get-Content -Raw -Path $global:State.StatePath | ConvertFrom-Json
        $appObjectId = $s.ApplicationObjectId
        $appClientId = $s.ApplicationClientId
      } catch {}
    }

    $lblCid = New-Object System.Windows.Controls.TextBlock
    $lblCid.Text = "Application (Client) ID:"
    $panel.Children.Add($lblCid) | Out-Null
    $tbCid = New-Object System.Windows.Controls.TextBox
    $tbCid.Text = ($appClientId ?? "")
    $panel.Children.Add($tbCid) | Out-Null

    $lblApp = New-Object System.Windows.Controls.TextBlock
    $lblApp.Text = "Application Object ID (optional; auto from Step 3):"
    $panel.Children.Add($lblApp) | Out-Null
    $tbApp = New-Object System.Windows.Controls.TextBox
    $tbApp.Text = ($appObjectId ?? "")
    $panel.Children.Add($tbApp) | Out-Null

    $lblMonths = New-Object System.Windows.Controls.TextBlock
    $lblMonths.Text = "Secret validity in months (1-24):"
    $panel.Children.Add($lblMonths) | Out-Null
    $tbMonths = New-Object System.Windows.Controls.TextBox
    $tbMonths.Text = "24"
    $panel.Children.Add($tbMonths) | Out-Null

    @{ AppObjectId = $tbApp; AppClientId = $tbCid; Months = $tbMonths }
  } -OnRun {
    param($vals, $out)
    $appObjectId = ($vals.AppObjectId ?? "").Trim()
    $appClientId = ($vals.AppClientId ?? "").Trim()
    if ([string]::IsNullOrWhiteSpace($appObjectId) -and [string]::IsNullOrWhiteSpace($appClientId)) {
      Append-Output $out "Please provide Application (Client) ID or Application Object ID."
      return
    }

    $months = 24
    try {
      [int]$parsed = 24
      [int]::TryParse(($vals.Months ?? "24"), [ref]$parsed) | Out-Null
      if ($parsed -ge 1 -and $parsed -le 24) { $months = $parsed }
    } catch {}

    $statePathLiteral = $global:State.StatePath.Replace('\', '\\')
    Start-AsyncConsole -Title "SpecterX Purview: Create Client Secret" -Command @"
`$appObjectId = '$appObjectId'
`$appClientId = '$appClientId'
`$months = $months
`$statePath = '$statePathLiteral'

Write-Host 'Connecting to Microsoft Graph...' -ForegroundColor Yellow
Connect-MgGraph -Scopes 'Application.ReadWrite.All','Directory.ReadWrite.All' -NoWelcome

if ([string]::IsNullOrWhiteSpace(`$appObjectId)) {
  if ([string]::IsNullOrWhiteSpace(`$appClientId)) { throw 'No Application Object ID or Client ID provided.' }
  `$app = Get-MgApplication -Filter "appId eq '`$appClientId'" -ConsistencyLevel eventual -CountVariable ac | Select-Object -First 1
  if (-not `$app -or -not `$app.Id) { throw 'Could not resolve Application Object ID from Client ID.' }
  `$appObjectId = `$app.Id
  Write-Host ('Resolved Application ObjectId: ' + `$appObjectId)
}

`$secretEnd = (Get-Date).AddMonths(`$months)
`$pwd = Add-MgApplicationPassword -ApplicationId `$appObjectId -PasswordCredential @{ displayName = 'SpecterX Purview Secret'; endDateTime = `$secretEnd }
if (-not `$pwd -or [string]::IsNullOrWhiteSpace(`$pwd.SecretText)) { throw 'Failed to create client secret.' }

Write-Host ('Secret expires (UTC): ' + `$secretEnd.ToString('u'))
Write-Host ('Secret value (copy now): ' + `$pwd.SecretText) -ForegroundColor Yellow

if (Test-Path `$statePath) { `$curr = Get-Content -Raw -Path `$statePath | ConvertFrom-Json } else { `$curr = [pscustomobject]@{} }
`$curr | Add-Member -NotePropertyName 'ClientSecretValue' -NotePropertyValue `$pwd.SecretText -Force
`$curr | Add-Member -NotePropertyName 'SecretExpiresUtc' -NotePropertyValue `$secretEnd.ToString('u') -Force
`$json = `$curr | ConvertTo-Json -Depth 10
Set-Content -Path `$statePath -Value `$json -NoNewline -Encoding UTF8
Write-Host 'Saved client secret to state file.' -ForegroundColor DarkGreen
"@
    Append-Output $out "Opened console for Step 4."
  }
}

# ---------------------- Step 5 ----------------------------
Add-NumberedRow -Index 5 -Text "Grant permission and admin consent" -OnClick {
  Show-StepDialog -Title "Step 5 - Grant permissions and admin consent" -Explanation @"
Adds and consents the required permission:
 - SensitivityLabels.Read.All (Application)
"@ -BuildInputs {
    param($panel)
    $tenantId = ""; $tenantDomain = ""; $spObjectId = ""; $appClientId = ""; $appObjectId = ""
    if (Test-Path $global:State.StatePath) {
      try {
        $s = Get-Content -Raw -Path $global:State.StatePath | ConvertFrom-Json
        $tenantId = $s.TenantId
        $tenantDomain = $s.TenantDomain
        $spObjectId = $s.ServicePrincipalObjectId
        $appClientId = $s.ApplicationClientId
        $appObjectId = $s.ApplicationObjectId
      } catch {}
    }

    $lblTid = New-Object System.Windows.Controls.TextBlock
    $lblTid.Text = "Tenant ID:"
    $panel.Children.Add($lblTid) | Out-Null
    $tbTid = New-Object System.Windows.Controls.TextBox
    $tbTid.Text = ($tenantId ?? "")
    $panel.Children.Add($tbTid) | Out-Null

    $lblDom = New-Object System.Windows.Controls.TextBlock
    $lblDom.Text = "Tenant Domain (optional fallback):"
    $panel.Children.Add($lblDom) | Out-Null
    $tbDom = New-Object System.Windows.Controls.TextBox
    $tbDom.Text = ($tenantDomain ?? "")
    $panel.Children.Add($tbDom) | Out-Null

    $lblSp = New-Object System.Windows.Controls.TextBlock
    $lblSp.Text = "Service Principal Object ID (preferred):"
    $panel.Children.Add($lblSp) | Out-Null
    $tbSp = New-Object System.Windows.Controls.TextBox
    $tbSp.Text = ($spObjectId ?? "")
    $panel.Children.Add($tbSp) | Out-Null

    $lblCid = New-Object System.Windows.Controls.TextBlock
    $lblCid.Text = "Application Client ID (fallback):"
    $panel.Children.Add($lblCid) | Out-Null
    $tbCid = New-Object System.Windows.Controls.TextBox
    $tbCid.Text = ($appClientId ?? "")
    $panel.Children.Add($tbCid) | Out-Null

    $lblAoid = New-Object System.Windows.Controls.TextBlock
    $lblAoid.Text = "Application Object ID (optional; auto from Client ID):"
    $panel.Children.Add($lblAoid) | Out-Null
    $tbAoid = New-Object System.Windows.Controls.TextBox
    $tbAoid.Text = ($appObjectId ?? "")
    $panel.Children.Add($tbAoid) | Out-Null

    @{ TenantId = $tbTid; TenantDomain = $tbDom; ServicePrincipalObjectId = $tbSp; ApplicationClientId = $tbCid; ApplicationObjectId = $tbAoid }
  } -OnRun {
    param($vals, $out)
    $tenantId = ($vals.TenantId ?? "").Trim()
    $tenantDom = ($vals.TenantDomain ?? "").Trim()
    $tenantHint = if (-not [string]::IsNullOrWhiteSpace($tenantId)) { $tenantId } elseif (-not [string]::IsNullOrWhiteSpace($tenantDom)) { $tenantDom } else { "" }
    if ([string]::IsNullOrWhiteSpace($tenantHint)) {
      Append-Output $out "Please provide Tenant ID or Tenant Domain."
      return
    }

    $spObjectId = ($vals.ServicePrincipalObjectId ?? "").Trim()
    $appClientId = ($vals.ApplicationClientId ?? "").Trim()
    $appObjectId = ($vals.ApplicationObjectId ?? "").Trim()
    if ([string]::IsNullOrWhiteSpace($spObjectId) -and [string]::IsNullOrWhiteSpace($appClientId) -and [string]::IsNullOrWhiteSpace($appObjectId)) {
      Append-Output $out "Provide Service Principal Object ID, Application Client ID, or Application Object ID."
      return
    }

    $statePathLiteral = $global:State.StatePath.Replace('\', '\\')
    Start-AsyncConsole -Title "SpecterX Purview: Grant Permission + Consent" -Command @"
`$tenantHint = '$tenantHint'
`$spObjectId = '$spObjectId'
`$appClientId = '$appClientId'
`$appObjectId = '$appObjectId'
`$statePath = '$statePathLiteral'

Write-Host 'Connecting to Microsoft Graph...' -ForegroundColor Yellow
Connect-MgGraph -Scopes 'AppRoleAssignment.ReadWrite.All','Application.Read.All','Directory.Read.All' -TenantId `$tenantHint -NoWelcome

if ([string]::IsNullOrWhiteSpace(`$spObjectId)) {
  if ([string]::IsNullOrWhiteSpace(`$appClientId)) { throw 'No service principal or app client id provided.' }
  `$sp = Get-MgServicePrincipal -All | Where-Object { `$_.AppId -eq `$appClientId } | Select-Object -First 1
} else {
  `$sp = Get-MgServicePrincipal -ServicePrincipalId `$spObjectId
}
if (-not `$sp -or -not `$sp.Id) { throw 'Could not find service principal for target app.' }
Write-Host ('Target Service Principal ObjectId: ' + `$sp.Id)

# Resolve application object id so permission appears in "Configured permissions"
if ([string]::IsNullOrWhiteSpace(`$appObjectId)) {
  if (-not [string]::IsNullOrWhiteSpace(`$appClientId)) {
    `$appObj = Get-MgApplication -All | Where-Object { `$_.AppId -eq `$appClientId } | Select-Object -First 1
    if (`$appObj -and `$appObj.Id) { `$appObjectId = `$appObj.Id }
  }
}
if ([string]::IsNullOrWhiteSpace(`$appObjectId)) {
  Write-Host 'Warning: could not resolve Application ObjectId. Will still grant consent, but portal may show it under "Other permissions granted".' -ForegroundColor DarkYellow
} else {
  Write-Host ('Target Application ObjectId: ' + `$appObjectId)
}

Write-Host 'Resolving Microsoft Graph service principal...' -ForegroundColor Yellow
`$graphSp = Get-MgServicePrincipal -All | Where-Object { `$_.AppId -eq '00000003-0000-0000-c000-000000000000' } | Select-Object -First 1
if (-not `$graphSp -or -not `$graphSp.Id) { throw 'Microsoft Graph service principal not found.' }

`$role = `$graphSp.AppRoles | Where-Object { `$_.Value -eq 'SensitivityLabels.Read.All' -and `$_.AllowedMemberTypes -contains 'Application' } | Select-Object -First 1
if (-not `$role) { throw 'Graph app role SensitivityLabels.Read.All (Application) not found.' }

# 1) Ensure permission is configured on the app registration (requiredResourceAccess)
if (-not [string]::IsNullOrWhiteSpace(`$appObjectId)) {
  Write-Host 'Ensuring requiredResourceAccess includes SensitivityLabels.Read.All...' -ForegroundColor Yellow
  `$appForReq = Get-MgApplication -ApplicationId `$appObjectId
  if (-not `$appForReq) { throw 'Could not read application for requiredResourceAccess update.' }

  `$req = @()
  foreach (`$r in @(`$appForReq.RequiredResourceAccess)) {
    if (-not `$r) { continue }
    `$ra = @()
    foreach (`$a in @(`$r.ResourceAccess)) {
      if (-not `$a) { continue }
      `$ra += @{ id = [string]`$a.Id; type = [string]`$a.Type }
    }
    `$req += @{ resourceAppId = [string]`$r.ResourceAppId; resourceAccess = `$ra }
  }

  `$graphReq = `$req | Where-Object { `$_.resourceAppId -eq '00000003-0000-0000-c000-000000000000' } | Select-Object -First 1
  if (`$graphReq) {
    `$exists = `$false
    foreach (`$x in @(`$graphReq.resourceAccess)) {
      if (([string]`$x.id).ToLower() -eq ([string]`$role.Id).ToLower() -and ([string]`$x.type) -eq 'Role') { `$exists = `$true; break }
    }
    if (-not `$exists) { `$graphReq.resourceAccess += @{ id = [string]`$role.Id; type = 'Role' } }
  } else {
    `$req += @{
      resourceAppId  = '00000003-0000-0000-c000-000000000000'
      resourceAccess = @(@{ id = [string]`$role.Id; type = 'Role' })
    }
  }

  `$body = @{ requiredResourceAccess = `$req } | ConvertTo-Json -Depth 12
  Invoke-MgGraphRequest -Method PATCH -Uri ('https://graph.microsoft.com/v1.0/applications/' + `$appObjectId) -Body `$body -ContentType 'application/json'
  Write-Host 'Configured permission added to app registration list.' -ForegroundColor Green
}

# 2) Grant admin consent (service principal app role assignment)
`$existing = Get-MgServicePrincipalAppRoleAssignment -ServicePrincipalId `$sp.Id -All | Where-Object {
  `$_.ResourceId -eq `$graphSp.Id -and `$_.AppRoleId -eq `$role.Id
}
if (-not `$existing) {
  New-MgServicePrincipalAppRoleAssignment -ServicePrincipalId `$sp.Id -PrincipalId `$sp.Id -ResourceId `$graphSp.Id -AppRoleId `$role.Id | Out-Null
  Write-Host 'Permission assignment created.' -ForegroundColor Green
} else {
  Write-Host 'Permission assignment already exists.' -ForegroundColor DarkGreen
}
Write-Host 'Admin consent granted for SensitivityLabels.Read.All.' -ForegroundColor Green

if (Test-Path `$statePath) { `$curr = Get-Content -Raw -Path `$statePath | ConvertFrom-Json } else { `$curr = [pscustomobject]@{} }
`$curr | Add-Member -NotePropertyName 'RequestedPermission' -NotePropertyValue 'SensitivityLabels.Read.All' -Force
`$curr | Add-Member -NotePropertyName 'ServicePrincipalObjectId' -NotePropertyValue `$sp.Id -Force
if (-not [string]::IsNullOrWhiteSpace(`$appObjectId)) { `$curr | Add-Member -NotePropertyName 'ApplicationObjectId' -NotePropertyValue `$appObjectId -Force }
`$json = `$curr | ConvertTo-Json -Depth 10
Set-Content -Path `$statePath -Value `$json -NoNewline -Encoding UTF8
Write-Host 'Saved permission/consent status to state file.' -ForegroundColor DarkGreen
"@
    Append-Output $out "Opened console for Step 5."
  }
}

# ---------------------- Step 6 ----------------------------
Add-NumberedRow -Index 6 -Text "Print & save handoff (Tenant ID, Client ID, Client secret)" -OnClick {
  Show-StepDialog -Title "Step 6 - Print and save handoff values" -Explanation @"
This reads saved state and outputs the final handoff values:
 - Tenant ID
 - Client ID
 - Client secret
"@ -BuildInputs {
    param($panel)
    $lbl = New-Object System.Windows.Controls.TextBlock
    $lbl.Text = "Handoff will be saved to log folder as JSON."
    $panel.Children.Add($lbl) | Out-Null
    @{}
  } -OnRun {
    param($vals, $out)
    $statePath = $global:State.StatePath
    $handoffPath = Join-Path $script:LogRoot ("SpecterX-Purview-Handoff-" + (Get-Date -Format "yyyyMMdd_HHmmss") + ".json")

    if (-not (Test-Path $statePath)) {
      Append-Output $out "State file not found. Complete previous steps first."
      return
    }

    try {
      $s = Get-Content -Raw -Path $statePath | ConvertFrom-Json
      $tenantId = [string]$s.TenantId
      $clientId = [string]$s.ApplicationClientId
      $secret   = [string]$s.ClientSecretValue

      if ([string]::IsNullOrWhiteSpace($tenantId) -or [string]::IsNullOrWhiteSpace($clientId) -or [string]::IsNullOrWhiteSpace($secret)) {
        Append-Output $out "Missing TenantId / ClientId / ClientSecret in state. Complete Steps 2-4 first."
        return
      }

      $handoff = [ordered]@{
        TenantId     = $tenantId
        ClientId     = $clientId
        ClientSecret = $secret
      }
      $json = $handoff | ConvertTo-Json -Depth 4
      Set-Content -Path $handoffPath -Value $json -NoNewline -Encoding UTF8

      Append-Output $out ""
      Append-Output $out "=== Purview Integration Handoff ==="
      Append-Output $out $json
      Append-Output $out ""
      Append-Output $out ("Saved: " + $handoffPath)

      Append-Status ""
      Append-Status "=== Purview Integration Handoff ==="
      Append-Status ("Tenant ID : " + $tenantId)
      Append-Status ("Client ID : " + $clientId)
      Append-Status ("Client secret captured and saved to JSON.")
    } catch {
      Append-Output $out ("Failed to generate handoff: " + $_.Exception.Message)
    }
  }
}

$win.Add_Closed({ Stop-SpxLogging })
$win.ShowDialog() | Out-Null

